{"command":"cat <<'EOF' > /tmp/test_lw.c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef int BROTLI_BOOL;
typedef struct BrotliEncoderStateStruct BrotliEncoderState;
typedef struct BrotliDecoderStateStruct BrotliDecoderState;

BrotliEncoderState* BrotliEncoderCreateInstance(void*, void*, void*);
void BrotliEncoderDestroyInstance(BrotliEncoderState*);
BROTLI_BOOL BrotliEncoderSetParameter(BrotliEncoderState*, int, uint32_t);
BROTLI_BOOL BrotliEncoderCompressStream(
    BrotliEncoderState*, int, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);
BROTLI_BOOL BrotliEncoderIsFinished(BrotliEncoderState*);

BrotliDecoderState* BrotliDecoderCreateInstance(void*, void*, void*);
void BrotliDecoderDestroyInstance(BrotliDecoderState*);
BROTLI_BOOL BrotliDecoderSetParameter(BrotliDecoderState*, int, uint32_t);
int BrotliDecoderDecompressStream(
    BrotliDecoderState*, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);

int main() {
    BrotliEncoderState* enc = BrotliEncoderCreateInstance(NULL, NULL, NULL);
    if (!enc) { printf("Enc create failed\n"); return 1; }
    BrotliEncoderSetParameter(enc, 1, 11); // Quality 11
    BrotliEncoderSetParameter(enc, 2, 26); // Lgwin 26
    BrotliEncoderSetParameter(enc, 6, 1);  // Large window 1

    const char* input = "Hello large window brotli compression test!!!";
    size_t in_len = strlen(input);
    const uint8_t* next_in = (const uint8_t*)input;

    uint8_t out[1024];
    uint8_t* next_out = out;
    size_t out_len = sizeof(out);

    BROTLI_BOOL ok = BrotliEncoderCompressStream(enc, 2, &in_len, &next_in, &out_len, &next_out, NULL);
    size_t compressed_size = sizeof(out) - out_len;
    printf("Compress ok: %d, compressed size: %zu\n", ok, compressed_size);
    BrotliEncoderDestroyInstance(enc);

    // Now decompress
    BrotliDecoderState* dec = BrotliDecoderCreateInstance(NULL, NULL, NULL);
    BrotliDecoderSetParameter(dec, 1, 1); // Large window 1

    in_len = compressed_size;
    next_in = out;
    uint8_t decomp[1024];
    next_out = decomp;
    out_len = sizeof(decomp);

    int res = BrotliDecoderDecompressStream(dec, &in_len, &next_in, &out_len, &next_out, NULL);
    size_t decomp_size = sizeof(decomp) - out_len;
    decomp[decomp_size] = '\0';
    printf("Decompress result: %d, decompressed: '%s'\n", res, decomp);
    BrotliDecoderDestroyInstance(dec);

    return 0;
}
EOF
gcc /tmp/test_lw.c -l:libbrotlienc.so.1 -l:libbrotlidec.so.1 -o /tmp/test_lw
/tmp/test_lw
rm -f /tmp/test_lw.c /tmp/test_lw"}

