{"command":"cat <<'EOF' > /tmp/test_meta.c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef int BROTLI_BOOL;
typedef struct BrotliEncoderStateStruct BrotliEncoderState;

BrotliEncoderState* BrotliEncoderCreateInstance(void*, void*, void*);
void BrotliEncoderDestroyInstance(BrotliEncoderState*);
BROTLI_BOOL BrotliEncoderSetParameter(BrotliEncoderState*, int, uint32_t);
BROTLI_BOOL BrotliEncoderCompressStream(
    BrotliEncoderState*, int op, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);

int main() {
    BrotliEncoderState* enc = BrotliEncoderCreateInstance(NULL, NULL, NULL);
    if (!enc) return 1;

    // Pass metadata (op = 3)
    const char* comment = "testcomment";
    size_t comment_len = strlen(comment);
    const uint8_t* next_in = (const uint8_t*)comment;

    uint8_t out[1024];
    uint8_t* next_out = out;
    size_t out_len = sizeof(out);

    // BROTLI_ENCODER_OPERATION_EMIT_METADATA = 3
    BROTLI_BOOL ok = BrotliEncoderCompressStream(enc, 3, &comment_len, &next_in, &out_len, &next_out, NULL);

    // Pass data (op = 2 finish)
    const char* input = "hello world\n";
    size_t in_len = strlen(input);
    next_in = (const uint8_t*)input;

    ok = BrotliEncoderCompressStream(enc, 2, &in_len, &next_in, &out_len, &next_out, NULL);

    size_t compressed_size = sizeof(out) - out_len;
    printf("Compress ok: %d, compressed size: %zu\n", ok, compressed_size);
    for (size_t i = 0; i < compressed_size; i++) {
        printf("%02x", out[i]);
    }
    printf("\n");
    BrotliEncoderDestroyInstance(enc);
    return 0;
}
EOF
gcc /tmp/test_meta.c -l:libbrotlienc.so.1 -o /tmp/test_meta
/tmp/test_meta
rm -f /tmp/test_meta.c /tmp/test_meta"}

