#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef int BROTLI_BOOL;
typedef struct BrotliDecoderStateStruct BrotliDecoderState;

BrotliDecoderState* BrotliDecoderCreateInstance(void*, void*, void*);
void BrotliDecoderDestroyInstance(BrotliDecoderState*);
int BrotliDecoderDecompressStream(
    BrotliDecoderState*, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);
BROTLI_BOOL BrotliDecoderIsFinished(BrotliDecoderState*);

int main() {
    FILE* f = fopen("/tmp/brotli_test/concat.br", "rb");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t* in_buf = malloc(sz);
    fread(in_buf, 1, sz, f);
    fclose(f);

    size_t avail_in = sz;
    const uint8_t* next_in = in_buf;

    uint8_t out_buf[1024];

    while (avail_in > 0) {
        BrotliDecoderState* dec = BrotliDecoderCreateInstance(NULL, NULL, NULL);
        while (1) {
            size_t avail_out = sizeof(out_buf);
            uint8_t* next_out = out_buf;
            int res = BrotliDecoderDecompressStream(dec, &avail_in, &next_in, &avail_out, &next_out, NULL);
            size_t written = sizeof(out_buf) - avail_out;
            if (written > 0) {
                fwrite(out_buf, 1, written, stdout);
            }
            if (res == 1) { // BROTLI_DECODER_RESULT_SUCCESS
                break;
            }
            if (res == 0) { // Error
                fprintf(stderr, "Decompress error\n");
                return 1;
            }
        }
        BrotliDecoderDestroyInstance(dec);
    }
    free(in_buf);
    return 0;
}
