typedef void (*brotli_free_func)(void* opaque, void* address);

/* Encoder Types & Constants */
typedef struct BrotliEncoderStateStruct BrotliEncoderState;

typedef enum {
  BROTLI_PARAM_MODE = 0,
  BROTLI_PARAM_QUALITY = 1,
