  BROTLI_ENCODER_OPERATION_PROCESS = 0,
  BROTLI_ENCODER_OPERATION_FLUSH = 1,
  BROTLI_ENCODER_OPERATION_FINISH = 2,
  BROTLI_ENCODER_OPERATION_EMIT_METADATA = 3
} BrotliEncoderOperation;

BrotliEncoderState* BrotliEncoderCreateInstance(brotli_alloc_func alloc_func, brotli_free_func free_func, void* opaque);
