static void PrintHelp(const char* name, BROTLI_BOOL is_error) {
  FILE* media = is_error ? stdout : stderr;
  fprintf(media, "Usage: %s [OPTION]... [FILE]...\n", name);
  fprintf(media,
      "Options:\n"
      "  -#                          compression level (0-9)\n"
