    if (parsing_opts && arg[0] == '-' && arg[1] != '\0') {
      if (arg[1] == '-') {
        /* Long option */
        if (strcmp(arg, "--help") == 0) {
          PrintHelp(prog_name, BROTLI_FALSE);
          free(prog_buf); free(input_files);
          return 0;
        } else if (strcmp(arg, "--version") == 0) {
          fprintf(stdout, "brotli 1.2.0\n");
          free(prog_buf); free(input_files);
          return 0;
        } else if (strcmp(arg, "--stdout") == 0) {
          write_to_stdout = true;
        } else if (strcmp(arg, "--decompress") == 0) {
          decompress = true;
        } else if (strcmp(arg, "--force") == 0) {
          force_overwrite = true;
        } else if (strcmp(arg, "--rm") == 0) {
          junk_source = true;
        } else if (strcmp(arg, "--squash") == 0) {
          squash = true;
        } else if (strcmp(arg, "--keep") == 0) {
          junk_source = false;
        } else if (strcmp(arg, "--no-copy-stat") == 0) {
          copy_stat = false;
        } else if (strcmp(arg, "--test") == 0) {
          test_integrity = true;
          decompress = true;
        } else if (strcmp(arg, "--verbose") == 0) {
          verbose = true;
        } else if (strcmp(arg, "--concatenated") == 0) {
          concatenated = true;
        } else if (strcmp(arg, "--best") == 0) {
          quality = 11;
        } else {
          char* eq = strchr(arg, '=');
          if (!eq) {
            fprintf(stderr, "must pass the parameter as %s=value\n", arg);
            PrintHelp(prog_name, BROTLI_TRUE);
            free(prog_buf); free(input_files);
            return 1;
          }
          *eq = '\0';
          const char* opt_name = arg;
          const char* val = eq + 1;
          if (strcmp(opt_name, "--output") == 0) {
            if (write_to_stdout) {
              fprintf(stderr, "write to standard output already set (-o)\n");
              PrintHelp(prog_name, BROTLI_TRUE);
              free(prog_buf); free(input_files);
              return 1;
            }
            output_file = val;
          } else if (strcmp(opt_name, "--quality") == 0) {
            char* endp;
            long q = strtol(val, &endp, 10);
            if (*endp != '\0' || q < 0 || q > 11) {
              fprintf(stderr, "error parsing quality value [%s]\n", val);
              PrintHelp(prog_name, BROTLI_TRUE);
              free(prog_buf); free(input_files);
              return 1;
            }
            quality = (int)q;
          } else if (strcmp(opt_name, "--lgwin") == 0) {
            char* endp;
            long w = strtol(val, &endp, 10);
            if (*endp != '\0' || (w != 0 && (w < 10 || w > 24))) {
              fprintf(stderr, "error parsing lgwin value [%s]\n", val);
              PrintHelp(prog_name, BROTLI_TRUE);
              free(prog_buf); free(input_files);
              return 1;
            }
            lgwin = (int)w;
          } else if (strcmp(opt_name, "--large_window") == 0) {
            char* endp;
            long w = strtol(val, &endp, 10);
            if (*endp != '\0' || (w != 0 && (w < 10 || w > 30))) {
              fprintf(stderr, "error parsing lgwin value [%s]\n", val);
              PrintHelp(prog_name, BROTLI_TRUE);
              free(prog_buf); free(input_files);
              return 1;
            }
            lgwin = (int)w;
            large_window = true;
          } else if (strcmp(opt_name, "--comment") == 0) {
            if (!Base64Decode(val, comment, &comment_len)) {
              fprintf(stderr, "invalid base64-encoded comment\n");
              PrintHelp(prog_name, BROTLI_TRUE);
              free(prog_buf); free(input_files);
              return 1;
            }
            has_comment = true;
          } else if (strcmp(opt_name, "--dictionary") == 0) {
            dictionary_path = val;
          } else if (strcmp(opt_name, "--suffix") == 0) {
            suffix = val;
          } else {
            fprintf(stderr, "invalid parameter: [%s=%s]\n", opt_name + 2, val);
            PrintHelp(prog_name, BROTLI_TRUE);
            free(prog_buf); free(input_files);
            return 1;
          }
        }
      } else {
        /* Short option(s) */
        size_t len = strlen(arg);
        for (size_t j = 1; j < len; j++) {
          char c = arg[j];
          if (c >= '0' && c <= '9') {
            quality = c - '0';
          } else if (c == 'c') {
            write_to_stdout = true;
          } else if (c == 'd') {
            decompress = true;
          } else if (c == 'f') {
            force_overwrite = true;
          } else if (c == 'h') {
            PrintHelp(prog_name, BROTLI_FALSE);
            free(prog_buf); free(input_files);
            return 0;
          } else if (c == 'j') {
            junk_source = true;
          } else if (c == 's') {
            squash = true;
          } else if (c == 'k') {
            junk_source = false;
          } else if (c == 'n') {
            copy_stat = false;
          } else if (c == 't') {
            test_integrity = true;
            decompress = true;
          } else if (c == 'v') {
            verbose = true;
          } else if (c == 'K') {
            concatenated = true;
          } else if (c == 'V') {
            fprintf(stdout, "brotli 1.2.0\n");
            free(prog_buf); free(input_files);
            return 0;
          } else if (c == 'Z') {
            quality = 11;
          } else if (c == 'o' || c == 'q' || c == 'w' || c == 'C' || c == 'D' || c == 'S') {
            if (i + 1 >= argc) {
              fprintf(stderr, "expected parameter for argument -%c\n", c);
              PrintHelp(prog_name, BROTLI_TRUE);
              free(prog_buf); free(input_files);
              return 1;
            }
            const char* val = argv[++i];
            if (c == 'o') {
              if (write_to_stdout) {
                fprintf(stderr, "write to standard output already set (-o)\n");
                PrintHelp(prog_name, BROTLI_TRUE);
                free(prog_buf); free(input_files);
                return 1;
              }
              output_file = val;
            } else if (c == 'q') {
              char* endp;
              long q = strtol(val, &endp, 10);
              if (*endp != '\0' || q < 0 || q > 11) {
                fprintf(stderr, "error parsing quality value [%s]\n", val);
                PrintHelp(prog_name, BROTLI_TRUE);
                free(prog_buf); free(input_files);
                return 1;
              }
              quality = (int)q;
            } else if (c == 'w') {
              char* endp;
              long w = strtol(val, &endp, 10);
              if (*endp == '\0' && w >= 1 && w <= 9) {
                fprintf(stderr, "lgwin parameter (%ld) smaller than the minimum (10)\n", w);
                PrintHelp(prog_name, BROTLI_TRUE);
                free(prog_buf); free(input_files);
                return 1;
              }
              if (*endp != '\0' || (w != 0 && (w < 10 || w > 24))) {
                fprintf(stderr, "error parsing lgwin value [%s]\n", val);
                PrintHelp(prog_name, BROTLI_TRUE);
                free(prog_buf); free(input_files);
                return 1;
              }
              lgwin = (int)w;
            } else if (c == 'C') {
              if (!Base64Decode(val, comment, &comment_len)) {
                fprintf(stderr, "invalid base64-encoded comment\n");
                PrintHelp(prog_name, BROTLI_TRUE);
                free(prog_buf); free(input_files);
                return 1;
              }
              has_comment = true;
            } else if (c == 'D') {
              dictionary_path = val;
            } else if (c == 'S') {
              suffix = val;
            }
            break;
          } else {
            fprintf(stderr, "invalid argument -%c\n", c);
            PrintHelp(prog_name, BROTLI_TRUE);
            free(prog_buf); free(input_files);
            return 1;
          }
        }
      }
    } else {
      input_files[input_files_count++] = arg;
    }
  }

  if (input_files_count == 0) {
    input_files[input_files_count++] = "-";
  }

  /* Check dictionary file if specified */
  if (dictionary_path) {
    FILE* fdict = fopen(dictionary_path, "rb");
    if (!fdict) {
      fprintf(stderr, "failed to open dictionary file [%s]: %s\n", dictionary_path, strerror(errno));
      free(prog_buf); free(input_files);
      return 1;
    }
    fclose(fdict);
  }

  /* Check tty output */
  bool is_stdout_term = isatty(STDOUT_FILENO);
  if ((write_to_stdout || (input_files_count == 1 && strcmp(input_files[0], "-") == 0 && !output_file && !decompress))
      && is_stdout_term && !force_overwrite && !test_integrity) {
    fprintf(stderr, "Use -h help. Use -f to force output to a terminal.\n");
    free(prog_buf); free(input_files);
    return 1;
  }

  for (int f_idx = 0; f_idx < input_files_count; f_idx++) {
    const char* filename = input_files[f_idx];
    bool is_stdin = (strcmp(filename, "-") == 0);
    const char* display_name = is_stdin ? "con" : filename;

    FILE* f_in = NULL;
    uint64_t total_in = 0;
    uint64_t total_out = 0;

    if (is_stdin) {
      f_in = stdin;
    } else {
      f_in = fopen(filename, "rb");
      if (!f_in) {
        fprintf(stderr, "failed to open input file [%s]: %s\n", filename, strerror(errno));
        free(prog_buf); free(input_files);
        return 1;
      }
    }

    FILE* f_out = NULL;
    char* auto_out_path = NULL;
    const char* out_path = NULL;

    if (test_integrity) {
      f_out = NULL;
    } else if (write_to_stdout || (is_stdin && !output_file)) {
      f_out = stdout;
    } else if (output_file) {
      out_path = output_file;
    } else if (decompress) {
      size_t fn_len = strlen(filename);
      size_t suf_len = strlen(suffix);
      if (fn_len <= suf_len || strcmp(filename + fn_len - suf_len, suffix) != 0) {
        fprintf(stderr, "input file [%s] suffix mismatch\n", filename);
        if (!is_stdin) fclose(f_in);
        free(prog_buf); free(input_files);
        return 1;
      }
      auto_out_path = strndup(filename, fn_len - suf_len);
      out_path = auto_out_path;
    } else {
      size_t fn_len = strlen(filename);
      size_t suf_len = strlen(suffix);
      auto_out_path = malloc(fn_len + suf_len + 1);
      sprintf(auto_out_path, "%s%s", filename, suffix);
      out_path = auto_out_path;
    }

    if (!f_out && out_path) {
      if (access(out_path, F_OK) == 0 && !force_overwrite) {
        fprintf(stderr, "failed to open output file [%s]: File exists\n", out_path);
        if (!is_stdin) fclose(f_in);
        if (auto_out_path) free(auto_out_path);
        free(prog_buf); free(input_files);
        return 1;
      }
      f_out = fopen(out_path, "wb");
      if (!f_out) {
        fprintf(stderr, "failed to open output file [%s]: %s\n", out_path, strerror(errno));
        if (!is_stdin) fclose(f_in);
        if (auto_out_path) free(auto_out_path);
        free(prog_buf); free(input_files);
        return 1;
      }
    }

    double t_start = GetTimeSec();
    bool success = true;

    if (!decompress) {
      /* COMPRESSION */
      BrotliEncoderState* s = BrotliEncoderCreateInstance(NULL, NULL, NULL);
      if (!s) {
        success = false;
      } else {
        BrotliEncoderSetParameter(s, BROTLI_PARAM_QUALITY, (uint32_t)quality);
        if (lgwin > 0) {
          BrotliEncoderSetParameter(s, BROTLI_PARAM_LGWIN, (uint32_t)lgwin);
        }
        if (large_window) {
          BrotliEncoderSetParameter(s, BROTLI_PARAM_LARGE_WINDOW, 1);
        }

        if (!is_stdin) {
          struct stat st;
          if (stat(filename, &st) == 0 && st.st_size > 0 && st.st_size <= 1073741824) {
            BrotliEncoderSetParameter(s, BROTLI_PARAM_SIZE_HINT, (uint32_t)st.st_size);
          }
        }

        uint8_t out_buf[65536];

        if (has_comment && comment_len > 0) {
          size_t c_in = comment_len;
          const uint8_t* c_ptr = comment;
          size_t c_out = sizeof(out_buf);
          uint8_t* c_next_out = out_buf;
          BrotliEncoderCompressStream(s, BROTLI_ENCODER_OPERATION_EMIT_METADATA,
                                      &c_in, &c_ptr, &c_out, &c_next_out, NULL);
          size_t produced = sizeof(out_buf) - c_out;
          if (produced > 0 && f_out) {
            fwrite(out_buf, 1, produced, f_out);
            total_out += produced;
          }
        }

        uint8_t in_buf[65536];
        while (1) {
          size_t bytes_read = fread(in_buf, 1, sizeof(in_buf), f_in);
          total_in += bytes_read;
          BrotliEncoderOperation op = (bytes_read < sizeof(in_buf) && feof(f_in))
              ? BROTLI_ENCODER_OPERATION_FINISH : BROTLI_ENCODER_OPERATION_PROCESS;

          size_t avail_in = bytes_read;
          const uint8_t* next_in = in_buf;

          while (1) {
            size_t avail_out = sizeof(out_buf);
            uint8_t* next_out = out_buf;
            BROTLI_BOOL ok = BrotliEncoderCompressStream(
                s, op, &avail_in, &next_in, &avail_out, &next_out, NULL);
            if (!ok) {
              success = false;
              break;
            }
            size_t produced = sizeof(out_buf) - avail_out;
            if (produced > 0 && f_out) {
              fwrite(out_buf, 1, produced, f_out);
              total_out += produced;
            }
            if (BrotliEncoderIsFinished(s)) break;
            if (avail_in == 0 && !BrotliEncoderHasMoreOutput(s)) break;
          }
          if (!success || op == BROTLI_ENCODER_OPERATION_FINISH) break;
        }
        BrotliEncoderDestroyInstance(s);
      }
    } else {
      /* DECOMPRESSION */
      uint8_t in_buf[65536];
      uint8_t out_buf[65536];

      size_t in_buf_offset = 0;
      size_t in_buf_size = 0;

      while (1) {
        BrotliDecoderState* s = BrotliDecoderCreateInstance(NULL, NULL, NULL);
        if (!s) { success = false; break; }
        if (large_window) {
          BrotliDecoderSetParameter(s, BROTLI_DECODER_PARAM_LARGE_WINDOW, 1);
        }

        while (1) {
          if (in_buf_offset >= in_buf_size) {
            in_buf_size = fread(in_buf, 1, sizeof(in_buf), f_in);
            in_buf_offset = 0;
            total_in += in_buf_size;
            if (in_buf_size == 0) break;
          }

          size_t avail_in = in_buf_size - in_buf_offset;
          const uint8_t* next_in = in_buf + in_buf_offset;

          if (has_comment && comment_len > 0) {
            /* Check comment presence in stream */
            bool comment_found = false;
            for (size_t i = 0; i + comment_len <= avail_in; i++) {
              if (memcmp(next_in + i, comment, comment_len) == 0) {
                comment_found = true;
                break;
              }
            }
            if (!comment_found) {
              BrotliDecoderDestroyInstance(s);
              success = false;
              break;
            }
          }

          size_t avail_out = sizeof(out_buf);
          uint8_t* next_out = out_buf;

          BrotliDecoderResult result = BrotliDecoderDecompressStream(
              s, &avail_in, &next_in, &avail_out, &next_out, NULL);

          size_t consumed = (in_buf_size - in_buf_offset) - avail_in;
          in_buf_offset += consumed;

          size_t produced = sizeof(out_buf) - avail_out;
          if (produced > 0 && f_out) {
            fwrite(out_buf, 1, produced, f_out);
          }
          total_out += produced;

          if (result == BROTLI_DECODER_RESULT_SUCCESS) {
            break;
          } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT) {
            continue;
          } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT) {
            continue;
          } else {
            success = false;
            break;
          }
        }

        if (!success) {
          BrotliDecoderDestroyInstance(s);
          break;
        }

        BROTLI_BOOL finished = BrotliDecoderIsFinished(s);
        BrotliDecoderDestroyInstance(s);

        if (!finished) {
          success = false;
          break;
        }

        if (!concatenated) break;
        if (in_buf_offset >= in_buf_size && feof(f_in)) break;
      }
    }

    if (!is_stdin) fclose(f_in);
    if (f_out && f_out != stdout) fclose(f_out);

    if (!success) {
      if (out_path && f_out != stdout) unlink(out_path);
      fprintf(stderr, "corrupt input [%s]\n", display_name);
      if (auto_out_path) free(auto_out_path);
      free(prog_buf); free(input_files);
      return 1;
    }

    double t_end = GetTimeSec();
    double duration = t_end - t_start;
    if (duration < 0.0) duration = 0.0;

    if (verbose) {
      if (!decompress) {
        fprintf(stderr, "Compressed [%s]: %llu B -> %llu B in %.2f sec\n",
                display_name, (unsigned long long)total_in, (unsigned long long)total_out, duration);
      } else {
        fprintf(stderr, "Decompressed [%s]: %llu B -> %llu B in %.2f sec\n",
                display_name, (unsigned long long)total_in, (unsigned long long)total_out, duration);
      }
    }

    if (!is_stdin && out_path && f_out != stdout) {
      if (copy_stat) {
        CopyStat(filename, out_path);
      }
      if (!decompress && squash && total_out >= total_in) {
        unlink(out_path);
      } else if (junk_source) {
        unlink(filename);
      }
    }

    if (auto_out_path) free(auto_out_path);
  }

  free(prog_buf);
  free(input_files);
  return 0;
}
EOF
"}

