#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef int BROTLI_BOOL;
typedef struct BrotliEncoderStateStruct BrotliEncoderState;

BrotliEncoderState* BrotliEncoderCreateInstance(void*, void*, void*);
void BrotliEncoderDestroyInstance(BrotliEncoderState*);
BROTLI_BOOL BrotliEncoderSetParameter(BrotliEncoderState*, int op, uint32_t val);
BROTLI_BOOL BrotliEncoderCompressStream(
    BrotliEncoderState*, int op, size_t*, const uint8_t**, size_t*, uint8_t**, size_t*);

int main() {
    const char* input = "Hello Brotli Compression Test 1234567890\n";
    size_t in_len = strlen(input);

    for (int mode = 0; mode <= 2; mode++) {
        for (int q = 0; q <= 11; q++) {
            for (int w = 0; w <= 24; w++) {
                BrotliEncoderState* enc = BrotliEncoderCreateInstance(NULL, NULL, NULL);
                BrotliEncoderSetParameter(enc, 0, mode); // BROTLI_PARAM_MODE
                BrotliEncoderSetParameter(enc, 1, q);    // BROTLI_PARAM_QUALITY
                if (w > 0) BrotliEncoderSetParameter(enc, 2, w); // BROTLI_PARAM_LGWIN

                size_t avail_in = in_len;
                const uint8_t* next_in = (const uint8_t*)input;
                uint8_t out[1024];
                size_t avail_out = sizeof(out);
                uint8_t* next_out = out;

                BrotliEncoderCompressStream(enc, 2, &avail_in, &next_in, &avail_out, &next_out, NULL);
                size_t comp_len = sizeof(out) - avail_out;

                if (out[0] == 0xa1 && out[1] == 0x40 && out[2] == 0x01) {
                    printf("MATCH FOUND! mode=%d, q=%d, w=%d, len=%zu\n", mode, q, w, comp_len);
                }
                BrotliEncoderDestroyInstance(enc);
            }
        }
    }
    return 0;
}
