        if (has_comment && comment_len > 0) {
          size_t c_in = comment_len;
          const uint8_t* c_ptr = comment;
          size_t c_out = sizeof(out_buf);
          uint8_t* c_next_out = out_buf;
          BrotliEncoderCompressStream(s, BROTLI_ENCODER_OPERATION_EMIT_METADATA,
                                      &c_in, &c_ptr, &c_out, &c_next_out, NULL);
          size_t produced = sizeof(out_buf) - c_out;
          if (produced > 0 && f_out) {
            fwrite(out_buf, 1, produced, f_out);
            total_out += produced;
          }
        }

        uint8_t in_buf[65536];
        while (1) {
          size_t bytes_read = fread(in_buf, 1, sizeof(in_buf), f_in);
          total_in += bytes_read;
          BrotliEncoderOperation op = (bytes_read < sizeof(in_buf) && feof(f_in))
              ? BROTLI_ENCODER_OPERATION_FINISH : BROTLI_ENCODER_OPERATION_PROCESS;

          size_t avail_in = bytes_read;
          const uint8_t* next_in = in_buf;

          while (1) {
            size_t avail_out = sizeof(out_buf);
            uint8_t* next_out = out_buf;
            BROTLI_BOOL ok = BrotliEncoderCompressStream(
                s, op, &avail_in, &next_in, &avail_out, &next_out, NULL);
            if (!ok) {
              success = false;
              break;
            }
            size_t produced = sizeof(out_buf) - avail_out;
            if (produced > 0 && f_out) {
              fwrite(out_buf, 1, produced, f_out);
              total_out += produced;
            }
            if (BrotliEncoderIsFinished(s)) break;
            if (avail_in == 0 && !BrotliEncoderHasMoreOutput(s)) break;
          }
          if (!success || op == BROTLI_ENCODER_OPERATION_FINISH) break;
        }
        BrotliEncoderDestroyInstance(s);
      }
    } else {
      /* DECOMPRESSION */
      uint8_t in_buf[65536];
      uint8_t out_buf[65536];

      size_t in_buf_offset = 0;
      size_t in_buf_size = 0;

      while (1) {
        BrotliDecoderState* s = BrotliDecoderCreateInstance(NULL, NULL, NULL);
        if (!s) { success = false; break; }
        if (large_window) {
          BrotliDecoderSetParameter(s, BROTLI_DECODER_PARAM_LARGE_WINDOW, 1);
        }

        while (1) {
          if (in_buf_offset >= in_buf_size) {
            in_buf_size = fread(in_buf, 1, sizeof(in_buf), f_in);
            in_buf_offset = 0;
            total_in += in_buf_size;
            if (in_buf_size == 0) break;
          }

          size_t avail_in = in_buf_size - in_buf_offset;
          const uint8_t* next_in = in_buf + in_buf_offset;

          if (has_comment && comment_len > 0) {
            /* Check comment presence in stream */
            bool comment_found = false;
            for (size_t i = 0; i + comment_len <= avail_in; i++) {
              if (memcmp(next_in + i, comment, comment_len) == 0) {
                comment_found = true;
                break;
              }
            }
            if (!comment_found) {
              BrotliDecoderDestroyInstance(s);
              success = false;
              break;
            }
          }

          size_t avail_out = sizeof(out_buf);
          uint8_t* next_out = out_buf;

          BrotliDecoderResult result = BrotliDecoderDecompressStream(
              s, &avail_in, &next_in, &avail_out, &next_out, NULL);

          size_t consumed = (in_buf_size - in_buf_offset) - avail_in;
          in_buf_offset += consumed;

          size_t produced = sizeof(out_buf) - avail_out;
          if (produced > 0 && f_out) {
            fwrite(out_buf, 1, produced, f_out);
          }
          total_out += produced;

          if (result == BROTLI_DECODER_RESULT_SUCCESS) {
            break;
          } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT) {
            continue;
          } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT) {
            continue;
          } else {
            success = false;
            break;
          }
        }

        if (!success) {
          BrotliDecoderDestroyInstance(s);
          break;
        }

        BROTLI_BOOL finished = BrotliDecoderIsFinished(s);
        BrotliDecoderDestroyInstance(s);

        if (!finished) {
          success = false;
          break;
        }

        if (!concatenated) {
          /* Check if there is extra unconsumed input remaining */
          if (in_buf_offset < in_buf_size || (!feof(f_in) && fread(in_buf, 1, 1, f_in) > 0)) {
            success = false;
          }
          break;
        }
        if (in_buf_offset >= in_buf_size && feof(f_in)) break;
      }
    }

    if (!is_stdin) fclose(f_in);
    if (f_out && f_out != stdout) fclose(f_out);

    if (!success) {
      if (out_path && f_out != stdout) unlink(out_path);
      fprintf(stderr, "corrupt input [%s]\n", display_name);
      if (auto_out_path) free(auto_out_path);
      exit_code = 1; goto cleanup_and_exit;
    }

    double t_end = GetTimeSec();
    double duration = t_end - t_start;
    if (duration < 0.0) duration = 0.0;

    if (verbose) {
      if (!decompress) {
        fprintf(stderr, "Compressed [%s]: %llu B -> %llu B in %.2f sec\n",
                display_name, (unsigned long long)total_in, (unsigned long long)total_out, duration);
      } else {
        fprintf(stderr, "Decompressed [%s]: %llu B -> %llu B in %.2f sec\n",
                display_name, (unsigned long long)total_in, (unsigned long long)total_out, duration);
      }
    }

    if (!is_stdin && out_path && f_out != stdout) {
      if (copy_stat) {
        CopyStat(filename, out_path);
      }
      if (!decompress && squash && total_out >= total_in) {
        unlink(out_path);
      } else if (junk_source) {
        unlink(filename);
      }
    }

    if (auto_out_path) free(auto_out_path);
  }

cleanup_and_exit:
  free(prog_buf);
  free(input_files);
  return exit_code;
}
