      }
    } else {
      input_files[input_files_count++] = arg;
    }
  }

  if (input_files_count == 0) {
    input_files[input_files_count++] = "-";
  }

  /* Check dictionary file if specified */
  if (dictionary_path) {
    FILE* fdict = fopen(dictionary_path, "rb");
    if (!fdict) {
      fprintf(stderr, "failed to open dictionary file [%s]: %s\n", dictionary_path, strerror(errno));
