      size_t suf_len = strlen(suffix);
      auto_out_path = malloc(fn_len + suf_len + 1);
      sprintf(auto_out_path, "%s%s", filename, suffix);
      out_path = auto_out_path;
    }

    if (!f_out && out_path) {
      if (access(out_path, F_OK) == 0 && !force_overwrite) {
        fprintf(stderr, "failed to open output file [%s]: File exists\n", out_path);
        if (!is_stdin) fclose(f_in);
        if (auto_out_path) free(auto_out_path);
        exit_code = 1; goto cleanup_and_exit;
      }
      f_out = fopen(out_path, "wb");
      if (!f_out) {
        fprintf(stderr, "failed to open output file [%s]: %s\n", out_path, strerror(errno));
        if (!is_stdin) fclose(f_in);
        if (auto_out_path) free(auto_out_path);
        exit_code = 1; goto cleanup_and_exit;
